solution.javascript:
function lruCacheOps(capacity, ops) {
  const nodes = new Map() // key -> list node
  const head = { prev: null, next: null } // head.next is the least recently used
  const tail = { prev: null, next: null } // tail.prev is the most recently used
  head.next = tail
  tail.prev = head
  const unlink = (node) => {
    node.prev.next = node.next
    node.next.prev = node.prev
  }
  const append = (node) => {
    node.prev = tail.prev
    node.next = tail
    tail.prev.next = node
    tail.prev = node
  }
  const out = []
  for (const op of ops) {
    if (op[0] === 'get') {
      const node = nodes.get(op[1])
      if (!node) {
        out.push(-1)
      } else {
        unlink(node)
        append(node) // now the most recent
        out.push(node.value)
      }
    } else {
      const [, key, value] = op
      if (nodes.has(key)) {
        const node = nodes.get(key)
        node.value = value
        unlink(node)
        append(node)
      } else {
        if (nodes.size === capacity) {
          const oldest = head.next
          unlink(oldest)
          nodes.delete(oldest.key)
        }
        const node = { key, value, prev: null, next: null }
        nodes.set(key, node)
        append(node)
      }
    }
  }
  return out
}
